import{_ as i,a0 as d,w as r,s as l,ao as o,I as p,x as s,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何用 rpm-ostree 数据库检查更新信息和更新日志 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 rpm-ostree 数据库检查更新信息和更新日志 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 rpm-ostree 数据库检查更新信息和更新日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 rpm-ostree 数据库检查更新信息和更新日志 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210915 How to check for update info and changelogs with rpm-ostree db","title":"如何用 rpm-ostree 数据库检查更新信息和更新日志","tag":"202109","desc":""},"relativePath":"202109/20210915 How to check for update info and changelogs with rpm-ostree db.md","filePath":"[post].md"}'),f={name:"202109/20210915 How to check for update info and changelogs with rpm-ostree db.md"};function b(c,e,g,m,u,h){const a=d("Link");return r(),l("div",null,[e[20]||(e[20]=o('<h1 id="如何用-rpm-ostree-数据库检查更新信息和更新日志" tabindex="-1">如何用 rpm-ostree 数据库检查更新信息和更新日志 <a class="header-anchor" href="#如何用-rpm-ostree-数据库检查更新信息和更新日志" aria-label="Permalink to “如何用 rpm-ostree 数据库检查更新信息和更新日志”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/09/rpm-ostree-db_changelog-816x345.jpg" alt=""></p><p>这篇文章将教你如何使用 <code>rpm-ostree</code> 数据库及其子命令检查更新、检查更改的软件包和阅读更新日志。</p><p>这些命令将在 Fedora Silverblue 上进行演示，并且应该在任何使用 <code>rpm-ostree</code> 的操作系统上工作。</p><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>假设你对不可更改的系统感兴趣。在基于容器技术构建用例时使用只读的基本系统听起来非常有吸引力，它会说服你选择使用 <code>rpm-ostree</code> 的发行版。</p>',6)),p("p",null,[e[2]||(e[2]=s("你现在发现自己在 ",-1)),n(a,{href:"https://fedoramagazine.org/what-is-silverblue/"},{default:t(()=>[...e[0]||(e[0]=[s("Fedora Silverblue",-1)])]),_:1}),e[3]||(e[3]=s("（或其他类似的发行版）上，你想检查更新。但你遇到了一个问题。虽然你可以通过 GNOME Software 找到 Fedora Silverblue 上的更新包，但你实际上无法阅读它们的更新日志。你也不能 ",-1)),n(a,{href:"https://fedoramagazine.org/use-dnf-updateinfo-to-read-update-changelogs/"},{default:t(()=>[...e[1]||(e[1]=[s("使用 dnf updateinfo 在命令行上读取它们",-1)])]),_:1}),e[4]||(e[4]=s("，因为主机系统上没有 DNF。",-1))]),e[21]||(e[21]=o(`<p>那么，你应该怎么做呢？嗯，<code>rpm-ostree</code> 有一些子命令可以在这种情况下提供帮助。</p><h3 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to “检查更新”">​</a></h3><p>第一步是检查更新。只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree upgrade --check</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>AvailableUpdate:</span></span>
<span class="line"><span>        Version: 34.20210905.0 (2021-09-05T20:59:47Z)</span></span>
<span class="line"><span>         Commit: d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>   GPGSignature: Valid signature by 8C5BA6990BDB26E19F2A1A801161AE6945719A39</span></span>
<span class="line"><span>  SecAdvisories: 1 moderate</span></span>
<span class="line"><span>           Diff: 4 upgraded</span></span></code></pre></div><p>请注意，虽然它没有在输出中告诉更新的软件包，但它显示了更新的提交为 <code>d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</code>。这在后面会很有用。</p><p>接下来你需要做的是找到你正在运行的当前部署的提交。运行 <code>rpm-ostree status</code> 以获得当前部署的<ruby>基提交<rt>BaseCommit</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree status</span></span>
<span class="line"><span>State: idle</span></span>
<span class="line"><span>Deployments:</span></span>
<span class="line"><span>● fedora:fedora/34/x86_64/silverblue</span></span>
<span class="line"><span>                   Version: 34.20210904.0 (2021-09-04T19:16:37Z)</span></span>
<span class="line"><span>                BaseCommit: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>              GPGSignature: Valid signature by 8C5BA6990BDB26E19F2A1A801161AE6945719A39</span></span>
<span class="line"><span>       RemovedBasePackages: ...</span></span>
<span class="line"><span>           LayeredPackages: ...</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>对于这个例子，基提交是<code>e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</code>。</p><p>现在你可以用 <code>rpm-ostree db diff [commit1] [commit2]</code> 找到这两个提交的差异。在这个命令中，<code>[commit1]</code> 将是当前部署的基提交，<code>[commit2]</code> 将是升级检查命令中的提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree db diff e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>ostree diff commit from: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>ostree diff commit to:   d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>Upgraded:</span></span>
<span class="line"><span>  soundtouch 2.1.1-6.fc34 -&gt; 2.1.2-1.fc34</span></span></code></pre></div><p><code>diff</code> 输出显示 <code>soundtouch</code> 被更新了，并指出了版本号。通过在前面的命令中加入 <code>-changelogs</code> 来查看更新日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree db diff e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4 --changelogs</span></span>
<span class="line"><span>ostree diff commit from: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>ostree diff commit to:   d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>Upgraded:</span></span>
<span class="line"><span>  soundtouch 2.1.1-6.fc34.x86_64 -&gt; 2.1.2-1.fc34.x86_64</span></span>
<span class="line"><span>    * dom ago 29 2021 Uwe Klotz &lt;uwe.klotz@gmail.com&gt; - 2.1.2-1</span></span>
<span class="line"><span>    - Update to new upstream version 2.1.2</span></span>
<span class="line"><span>      Bump version to 2.1.2 to correct incorrect version info in configure.ac</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    * sex jul 23 2021 Fedora Release Engineering &lt;releng@fedoraproject.org&gt; - 2.1.1-7</span></span>
<span class="line"><span>    - Rebuilt for https://fedoraproject.org/wiki/Fedora_35_Mass_Rebuild</span></span></code></pre></div><p>这个输出显示了提交说明以及版本号。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>使用 <code>rpm-ostree db</code>，你现在可以拥有相当于 <code>dnf check-update</code> 和 <code>dnf updateinfo</code> 的功能。</p><p>如果你想检查你所安装的更新的详细信息，这将非常有用。</p><hr>`,17)),p("p",null,[e[6]||(e[6]=s("via: ",-1)),n(a,{href:"https://fedoramagazine.org/how-to-check-for-update-info-and-changelogs-with-rpm-ostree-db/"},{default:t(()=>[...e[5]||(e[5]=[s("https://fedoramagazine.org/how-to-check-for-update-info-and-changelogs-with-rpm-ostree-db/",-1)])]),_:1})]),p("p",null,[e[11]||(e[11]=s("作者：",-1)),n(a,{href:"https://fedoramagazine.org/author/mateusrodcosta/"},{default:t(()=>[...e[7]||(e[7]=[s("Mateus Rodrigues Costa",-1)])]),_:1}),e[12]||(e[12]=s(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[9]||(e[9]=[s("geekpi",-1)])]),_:1}),e[14]||(e[14]=s(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[17]||(e[17]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...e[16]||(e[16]=[s("Linux中国",-1)])]),_:1}),e[19]||(e[19]=s(" 荣誉推出",-1))])])}const x=i(f,[["render",b]]);export{T as __pageData,x as default};
